"""Shaper Blender addon — one-click import of generated models.

Install: Blender -> Edit -> Preferences -> Add-ons -> Install... -> pick this file
-> enable "Shaper Importer". Then: 3D Viewport sidebar (N) -> Shaper -> point it
at your Shaper output folder -> Import Latest / pick a model.
"""
bl_info = {
    "name": "Shaper Importer",
    "author": "Shaper",
    "version": (1, 0, 0),
    "blender": (4, 0, 0),
    "location": "3D Viewport > Sidebar > Shaper",
    "description": "Import models generated by the Shaper AI 3D studio",
    "category": "Import-Export",
}

import bpy
from pathlib import Path


class ShaperSettings(bpy.types.PropertyGroup):
    output_folder: bpy.props.StringProperty(
        name="Output folder",
        description="The 'output' folder inside your Shaper project",
        subtype="DIR_PATH",
    )
    shade_smooth: bpy.props.BoolProperty(name="Shade smooth", default=True)


def _import_file(path: Path, smooth: bool):
    ext = path.suffix.lower()
    if ext == ".glb":
        bpy.ops.import_scene.gltf(filepath=str(path))
    elif ext == ".obj":
        bpy.ops.wm.obj_import(filepath=str(path))
    elif ext == ".stl":
        bpy.ops.wm.stl_import(filepath=str(path))
    elif ext == ".ply":
        bpy.ops.wm.ply_import(filepath=str(path))
    else:
        raise ValueError(f"Unsupported: {ext}")
    if smooth:
        for obj in bpy.context.selected_objects:
            if obj.type == "MESH":
                for poly in obj.data.polygons:
                    poly.use_smooth = True


class SHAPER_OT_import_latest(bpy.types.Operator):
    bl_idname = "shaper.import_latest"
    bl_label = "Import Latest Model"

    def execute(self, context):
        folder = Path(context.scene.shaper.output_folder)
        files = sorted(folder.glob("*.glb"), key=lambda p: p.stat().st_mtime)
        if not files:
            self.report({"ERROR"}, "No .glb files found in that folder")
            return {"CANCELLED"}
        _import_file(files[-1], context.scene.shaper.shade_smooth)
        self.report({"INFO"}, f"Imported {files[-1].name}")
        return {"FINISHED"}


class SHAPER_OT_import_file(bpy.types.Operator):
    bl_idname = "shaper.import_file"
    bl_label = "Import Model File..."
    filepath: bpy.props.StringProperty(subtype="FILE_PATH")

    def invoke(self, context, event):
        context.window_manager.fileselect_add(self)
        return {"RUNNING_MODAL"}

    def execute(self, context):
        _import_file(Path(self.filepath), context.scene.shaper.shade_smooth)
        return {"FINISHED"}


class SHAPER_PT_panel(bpy.types.Panel):
    bl_label = "Shaper"
    bl_space_type = "VIEW_3D"
    bl_region_type = "UI"
    bl_category = "Shaper"

    def draw(self, context):
        col = self.layout.column(align=True)
        col.prop(context.scene.shaper, "output_folder")
        col.prop(context.scene.shaper, "shade_smooth")
        col.operator("shaper.import_latest", icon="FILE_REFRESH")
        col.operator("shaper.import_file", icon="IMPORT")


classes = (ShaperSettings, SHAPER_OT_import_latest, SHAPER_OT_import_file, SHAPER_PT_panel)


def register():
    for c in classes:
        bpy.utils.register_class(c)
    bpy.types.Scene.shaper = bpy.props.PointerProperty(type=ShaperSettings)


def unregister():
    for c in reversed(classes):
        bpy.utils.unregister_class(c)
    del bpy.types.Scene.shaper


if __name__ == "__main__":
    register()
